#!/usr/bin/env bash
# Render the sequence diagrams (seq_*.mmd, generated by c4_model.py) to SVG and PNG with the LOCAL Mermaid CLI.
# Usage (repo root, Git Bash): bash docs/architecture/render_sequences.sh
# Needs the same one-time CLI install and local Chrome as render_mermaid_check.sh (TOOLS and CHROME env vars).
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
TOOLS="${TOOLS:-$HOME/.cache/mrcd-mmdc}"
CH="${CHROME:-C:/Program Files/Google/Chrome/Application/chrome.exe}"
TMP="$(mktemp -d)"
printf '{"executablePath":"%s","args":["--no-sandbox","--disable-gpu"]}' "$CH" > "$TMP/puppeteer.json"
for f in "$ROOT"/docs/architecture/seq_*.mmd; do
  b="${f%.mmd}"
  for ext in svg png; do
    "$TOOLS/node_modules/.bin/mmdc" -p "$TMP/puppeteer.json" -b white -w 1400 -i "$f" -o "$b.$ext" >/dev/null 2>&1
    echo "rendered $b.$ext"
  done
done
